AUDITED_TABLES = ('vehicles', 'vehicle_images', 'users', 'reservations', 'purchase_orders', 'payments', 'sales')

AUDIT_FUNCTION_SQL = """
CREATE OR REPLACE FUNCTION audit_row_change() RETURNS trigger AS $$
DECLARE
    old_row jsonb := CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN to_jsonb(OLD) - 'password_hash' END;
    new_row jsonb := CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN to_jsonb(NEW) - 'password_hash' END;
BEGIN
    -- Un UPDATE que no cambió nada no se audita
    IF TG_OP = 'UPDATE' AND old_row = new_row THEN
        RETURN NULL;
    END IF;
    INSERT INTO audit_log (table_name, record_id, action, old_data, new_data, changed_by)
    VALUES (
        TG_TABLE_NAME,
        COALESCE(new_row ->> 'id', old_row ->> 'id'),
        TG_OP,
        old_row,
        new_row,
        NULLIF(current_setting('app.user_id', true), '')
    );
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;
"""

